164|function claudeLaneCommands(path: string, setup: { owned: Map<string, string>; edited: Map<string, string> }): LaneCommand[] {
165|  const hooks = readJson(path)?.hooks;
166|  if (!hooks || typeof hooks !== 'object' || Array.isArray(hooks)) return [];
167|  const out: LaneCommand[] = [];
168|  for (const groups of Object.values(hooks as Record<string, unknown>)) {
169|    if (!Array.isArray(groups)) continue;
170|    for (const e of groups.flatMap((g) => (Array.isArray((g as { hooks?: unknown })?.hooks) ? (g as { hooks: unknown[] }).hooks : []))) {
171|      if (!e || typeof e !== 'object' || typeof (e as Record<string, unknown>).command !== 'string') continue;
172|      const entry = e as Record<string, unknown>;
173|      const hash = hookEntryHash(entry) ?? '';
174|      if (isTurnRuleEntry(entry)) out.push({ lane: 'turn-rule', command: entry.command as string });
